// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, addLinkToCollection, getLinks, getCollectionLinks, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

async function addLinkToCollectionWithoutLinkId(client: SkyrampClient, collectionId: any, expectedStatus = 400) {
    // Request Body
    const collectionsLinksPostRequestBody: string = `{
        "name": "tb-body-without-linkid"
    }`;

    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Execute Request
    const collectionsLinksPostResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/collections/{collections}/links",
        method: "POST",
        headers: headers,
        body: collectionsLinksPostRequestBody,
        pathParams: {"collections": collectionId}
    });

    // Generated Assertions
    expect(collectionsLinksPostResponse.statusCode, 'status code').toBe(expectedStatus);

    return collectionsLinksPostResponse;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const collectionsPostResponse = await createCollection(client, "tb-reject-collection");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-reject-collection");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const v1LinksPostResponse = await createLink(
        client,
        getResponseValue(collectionsPostResponse, "response.id"),
        "tb-reject-link",
        "https://example.com/tb-reject"
    );
    expect(v1LinksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksPostResponse, "response.name"), 'name').toBe("tb-reject-link");
    expect(getResponseValue(v1LinksPostResponse, "response.url"), 'url').toBe("https://example.com/tb-reject");
    expect(getResponseValue(v1LinksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(v1LinksPostResponse, "response.collectionId"), 'collectionId')
        .toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const collectionsLinksPostResponse = await addLinkToCollectionWithoutLinkId(
        client,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsLinksPostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(collectionsLinksPostResponse, "response"), 'response').toBe("linkId is required.");

    const collectionsLinksPost1Response = await addLinkToCollection(
        client,
        getResponseValue(collectionsPostResponse, "response.id"),
        2147480000,
        404
    );
    expect(collectionsLinksPost1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(collectionsLinksPost1Response, "response"), 'response').toBe("Link not found.");

    const linksPostResponse = await addLinkToCollection(client, "2147480001", 2147480000, 404);
    expect(linksPostResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(linksPostResponse, "response"), 'an unknown collection is refused without revealing it is unknown for a different reason')
        .toBe("Collection not found.");

    const abcLinksPostResponse = await addLinkToCollection(client, "abc", 2147480000, 400);
    expect(abcLinksPostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcLinksPostResponse, "response"), 'response').toBe("Invalid collection ID.");

    const collectionsLinksGetResponse = await getCollectionLinks(
        client,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsLinksGetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(collectionsLinksGetResponse, "response"), 'response').toBe("Method not allowed.");

    const v1LinksGetResponse = await getLinks(
        client,
        getResponseValue(v1LinksPostResponse, "response.collectionId"),
        "0"
    );
    expect(v1LinksGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksGetResponse, "response").length, 'no rejected request moved the link out of its collection').toBe(1);
    expect(getResponseValue(v1LinksGetResponse, "response.0.id"), 'id')
        .toBe(getResponseValue(v1LinksPostResponse, "response.id"));
    expect(getResponseValue(v1LinksGetResponse, "response.0.name"), 'name').toBe("tb-reject-link");
    expect(getResponseValue(v1LinksGetResponse, "response.0.collectionId"), 'collectionId')
        .toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(v1LinksGetResponse, "response.1"), 'no second link').toBeNull();

    // Request Body
    const v1LinksDeleteRequestBody: string = `{
        "linkIds": [
            918273652
        ]
    }`;

    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Execute Request
    const v1LinksDeleteResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/links",
        method: "DELETE",
        headers: headers,
        body: v1LinksDeleteRequestBody,
        dataOverride: {"linkIds.0": getResponseValue(v1LinksPostResponse, "response.id")}
    });

    // Generated Assertions
    expect(v1LinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(v1LinksDeleteResponse, "response.count"), 'exactly the link this test created was deleted').toBe(1);

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'id')
        .toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
